message.content:
{
  "sections": [
    {
      "title": "Why you were in the hospital",
      "bullets": [
        {
          "id": "b1",
          "text": "You had a right knee replacement surgery.",
          "sources": ["p1:L4", "term:TKA"]
        }
      ]
    },
    {
      "title": "What to do at home",
      "bullets": [
        {
          "id": "b2",
          "text": "Take Oxycodone 5 mg by mouth every 4 hours only when you need it for moderate to severe pain.",
          "sources": ["p1:L6", "term:PO", "term:q4h", "term:PRN"]
        },
        {
          "id": "b3",
          "text": "Do not drive while taking Oxycodone.",
          "sources": ["p1:L6"]
        },
        {
          "id": "b4",
          "text": "You can put weight on your leg if it feels okay. Use a walker.",
          "sources": ["p1:L11", "term:WBAT"]
        },
        {
          "id": "b5",
          "text": "Do exercises to help you move better 3 times a week.",
          "sources": ["p1:L11", "term:PT"]
        },
        {
          "id": "b6",
          "text": "Ice your knee for 20 minutes every 2 hours.",
          "sources": ["p1:L11"]
        },
        {
          "id": "b7",
          "text": "Keep your leg raised up.",
          "sources": ["p1:L11"]
        },
        {
          "id": "b8",
          "text": "Keep your dressing dry.",
          "sources": ["p1:L12"]
        },
        {
          "id": "b9",
          "text": "Do not take tub baths or swim until staples are removed.",
          "sources": ["p1:L12"]
        }
      ]
    },
    {
      "title": "Your follow-up visits",
      "bullets": [
        {
          "id": "b10",
          "text": "See your orthopedics doctor. Go in 2 weeks. This visit is for staple removal.",
          "sources": ["p1:L13"]
        }
      ]
    }
  ],
  "questions_for_your_doctor": [
    "When can I stop using the walker?",
    "How long should I keep icing my knee?",
    "When can I take a regular bath or shower?"
  ]
}
